package com.pokedaisy.app.companion.data

/**
 * Which game the app is currently reading. Every game is read from its native
 * RAM; Pokémon Unbound with its own data tables extracted from the Unbound ROM (*Unbound.kt, generated by
 * tools/telemetry-viewer/scripts/gen_unbound_data.py). Mirrors
 * tools/telemetry-viewer/game.go.
 */
// EMERALD shares FireRed's Gen 3 species/move/item/type tables (same internal
// indices) but has its own Hoenn region map + map-section names. GAIA and
// RADICAL_RED are FireRed-based hacks read the same way as vanilla FireRed
// (NATIVE_GAIA_V3_2 / NATIVE_RADICAL_RED_V4_1 in NativeReader.kt). Gaia
// relocated + grew its species table wholesale (see SpeciesNamesGaia.kt).
// Radical Red repoints its own tables (gSpeciesNames with its own ids up to
// 1349, long move names, gItems, gBaseStats): all read from its ROM by
// scripts/gen_cfru_tables.py, so none fall back to vanilla's.
// ODYSSEY - basic connectivity only so far (NATIVE_ODYSSEY inherits every
// vanilla FireRed RAM address unchanged, unverified beyond a live party/item
// check - see NativeReader.kt). Whether it renumbers species/items enough to
// need its own name tables (like Gaia/Radical Red did) hasn't been checked yet -
// falls through to the shared vanilla tables below (`else`) until it has.
// HEART_AND_SOUL/LAZARUS/ROWE are Emerald-based hacks (BPEE) - the first ones
// this project has supported; same "inherit NATIVE_EMERALD unchanged, verify
// live, re-derive only what's actually broken" starting point as the FireRed
// hacks above, via NATIVE_HEART_AND_SOUL/NATIVE_LAZARUS/NATIVE_ROWE in
// NativeReader.kt. Heart and Soul and Lazarus now have their own
// ROM-extracted tables (*Hns.kt / *Lazarus.kt, scripts/gen_expansion_tables.py).
enum class GameKind { FIRERED, EMERALD, UNBOUND, GAIA, RADICAL_RED, ODYSSEY, HEART_AND_SOUL, LAZARUS, ROWE, EMERALD_ROGUE, AMETHYST, EMERALD_SEAGLASS, CELIA, TMT2, SOULGOLD, YELLOW, GLAZED, IMPERIUM, QUETZAL, ORANGE_ISLANDS, RECHARGED_YELLOW, MARIOMON, SWORD_SHIELD, GS_CHRONICLES, CRYSTAL, CRYSTAL_CLEAR, PRISM,
    GOLD, SILVER, RED, BLUE, ELITE_REDUX, POLISHED_CRYSTAL, PLATINUM, HEARTGOLD, SOULSILVER, TEAM_ROCKET, BLACK, WHITE, BLACK2, WHITE2,
    WISHES, PURE_RED, PURE_BLUE, DREAMSTONE }

@Volatile
var activeGame: GameKind = GameKind.FIRERED

private inline val unbound get() = activeGame == GameKind.UNBOUND
private inline val emerald get() = activeGame == GameKind.EMERALD

/** The running ROM's language letter (its game code's last: BPE<S|D|F|I|J>); 'E' for English
 * and everything else. Set with [activeGame] by the Poller. */
var romLanguage = 'E'

/** The running retail ROM's game code when it has names of its own ("BPED", "AXVF"); else "". */
var romGameCode = ""

/** The running game's own names (EmeraldLanguages.kt); null for English and every game without them. */
val localText: GameText? get() = if (romGameCode.isEmpty()) null else gameText(romGameCode)

/** [shown]'s English name - what hand-written GUIDE entries tag areas with - for map section [mapsec]. */
fun englishMapSecName(mapsec: Int, shown: String): String =
    localText?.let { it.baseMapSecs[mapsec]?.name }
        ?: (if (activeGame == GameKind.QUETZAL && quetzalNames.places != 0) mapSecDataQuetzal[mapsec]?.name else null)
        ?: shown
