val activeTypeEffectiveness: Map<Int, Int> get() = when {
    pureRgb -> typeEffectivenessPureRgb
    yellow -> typeEffectivenessYellow
    polished -> typeEffectivenessPolishedCrystal
    prism -> typeEffectivenessPrism
    crystal -> typeEffectivenessCrystal
    unbound || cfruTypes -> typeEffectivenessUnbound
    // Seaglass uses the standard expansion type ids (TORCHIC is 11 = Fire), as Heart and Soul does.
    seaglass -> typeEffectivenessHns
    tmt2 -> typeEffectivenessTmt2
    hns -> typeEffectivenessHns
    lazarus -> typeEffectivenessLazarus
    soulGold -> typeEffectivenessSoulGold
    celia -> typeEffectivenessCelia
    rogue -> typeEffectivenessRogue
    glazed -> typeEffectivenessGlazed
    imperium -> typeEffectivenessImperium
    quetzal -> typeEffectivenessQuetzal
    rowe -> typeEffectivenessRowe
    orangeIslands -> typeEffectivenessOrangeIslands
    mariomon -> typeEffectivenessMariomon
    eliteRedux -> typeEffectivenessEliteRedux
    teamRocket -> typeEffectivenessTeamRocket
    wishes -> typeEffectivenessWishes
    dreamstone -> typeEffectivenessDreamstone
    odyssey -> fireRedHackOdyssey.typeChart ?: typeEffectiveness
    else -> frHack?.typeChart ?: typeEffectiveness
}
val activeTypeNames: Map<Int, String> get() = when {
    pureRgb -> typeNamesPureRgb
    yellow -> typeNamesYellow
    polished -> typeNamesPolishedCrystal
    prism -> typeNamesPrism
    crystal -> typeNamesCrystal
    unbound || cfruTypes -> typeNamesUnbound
    odyssey -> fireRedHackOdyssey.typeNamesMerged   // 9 is AETHER there (GitHub #206), not FireRed's ???
    seaglass -> typeNamesHns
    tmt2 -> typeNamesTmt2
    hns -> typeNamesHns
    lazarus -> typeNamesLazarus
    soulGold -> typeNamesSoulGold
    celia -> typeNamesCelia
    rogue -> typeNamesRogue
    glazed -> typeNamesGlazed
    imperium -> typeNamesImperium
    quetzal -> typeNamesQuetzal
    rowe -> typeNamesRowe
    orangeIslands -> typeNamesOrangeIslands
    mariomon -> typeNamesMariomon
    eliteRedux -> typeNamesEliteRedux
    teamRocket -> typeNamesTeamRocket
    wishes -> typeNamesWishes
    dreamstone -> typeNamesDreamstone
    else -> frHack?.typeNamesMerged ?: typeNames
}
val activeMapSecData: Map<Int, MapSecInfo> get() = localText?.mapSecData ?: when {
    gen4 -> emptyMap()   // no region map yet: the place comes from the map header (Telemetry.mapSecName)
    pureRgb -> mapSecDataPureRgb
    yellow -> mapSecDataYellow
    polished -> mapSecDataPolishedCrystal
    prism -> mapSecDataPrism
    crystalClear -> mapSecDataCrystalClear
    goldSilver -> mapSecDataGoldSilver
    crystal -> mapSecDataCrystal
    unbound -> mapSecDataUnbound
    // Seaglass keeps vanilla Hoenn mapsec ids (0x00 = Littleroot, confirmed live).
    emerald || seaglass || tmt2 -> mapSecDataEmerald
    // Own regions' names, text-only (no region-map image yet).
    hns -> mapSecDataHns
    lazarus -> mapSecDataLazarus
    soulGold -> mapSecDataSoulGold
    rogue -> mapSecDataRogue
    glazed -> mapSecDataGlazed
    imperium -> mapSecDataImperium
    quetzal -> quetzalMapSecs(quetzalNames.places)
    rowe -> mapSecDataRowe
    orangeIslands -> mapSecDataOrangeIslands
    // Galar, renamed in place over FireRed's sections; its map is drawn from the ROM (RomRegionMap).
    swordShield -> mapSecDataSwordShield
    // Johto and Kanto, renamed in place over FireRed's sections; its map is drawn from the ROM (RomRegionMap).
    gsChronicles -> mapSecDataGsChronicles
    rechargedYellow -> mapSecDataRechargedYellow
    mariomon -> if (mariomonV13) mapSecDataMariomonV13 else mapSecDataMariomon
    // Emerald's Hoenn sections and rects (and its own few past them), on Emerald's map.
    eliteRedux -> mapSecDataEliteRedux
    // Its own sections' names; no map of its own is drawn yet (it has several), so none is "on the map".
    teamRocket -> mapSecDataTeamRocket
    // Its own JOKAIM sections (Munen Village...) on its own region map; Emerald's / Kanto's leftovers off it.
    wishes -> mapSecDataWishes
    // Its own Cormoria sections (and Emerald's leftovers, off the map), on its own region map.
    dreamstone -> mapSecDataDreamstone
    else -> frHack?.mapSecsMerged ?: mapSecData
}
/**
 * Quetzal's Kanto and Sevii maps are FireRed's, pixel for pixel, drawn 3 tiles left and 2 up of
 * FireRed's screen (RomArt's QTZ_*: regionmap/quetzal_*.png), and its map sections keep FireRed's
 * ids: FireRed's rects and cursor grids, shifted, under Quetzal's own names.
 */
private const val QUETZAL_MAP_DX = -3
private const val QUETZAL_MAP_DY = -2
private val regionMapImagesQuetzalOnMap = arrayOf("quetzal_kanto", "quetzal_sevii123", "quetzal_sevii45", "quetzal_sevii67")
private val mapSecDataQuetzalOnMap: Map<Int, MapSecInfo> by lazy {
    mapSecDataQuetzal.mapValues { (id, q) ->
        val fr = mapSecData[id] ?: return@mapValues q
        if (fr.region < 0) q
        else if (fr.w == 0) q.copy(region = fr.region)  // placed by the grid alone
        else q.copy(region = fr.region, x = fr.x + QUETZAL_MAP_DX, y = fr.y + QUETZAL_MAP_DY, w = fr.w, h = fr.h)
    }
}
internal val regionLayoutsQuetzal: List<RegionLayout> by lazy {
    regionLayoutsFireRed.map { RegionLayout(it.offX + QUETZAL_MAP_DX, it.offY + QUETZAL_MAP_DY, it.w, it.h, it.none, it.layers, it.cellBytes) }
}

/**
 * Which language Quetzal shows each kind of name in - its own START > OPCIONES > TEXTO > IDIOMA
 * options, read from the save every sample ([readQuetzalNames]; set by the Poller): 0 English,
 * 1 Spanish, 2 Latin American Spanish (Portuguese, 3, isn't generated: English). Its Spanish
 * release only changes the LUGARES default. [QuetzalNamesGen.kt] holds the names that differ.
 */
@Volatile
var quetzalNames = QuetzalNames()

private val speciesNamesQuetzalSpanish by lazy { speciesNamesQuetzal + speciesNamesQuetzalEs }
private val moveDataQuetzalEs by lazy { moveDataQuetzal.renamed(moveNamesQuetzalEs) }
private val moveDataQuetzalLa by lazy { moveDataQuetzal.renamed(moveNamesQuetzalLa) }
private val itemNamesQuetzalSpanish by lazy { itemNamesQuetzal + itemNamesQuetzalEs }
private val itemNamesQuetzalLatam by lazy { itemNamesQuetzal + itemNamesQuetzalLa }
private val mapSecDataQuetzalEs by lazy { mapSecDataQuetzalOnMap.renamedSecs(mapSecNamesQuetzalEs) }
private val mapSecDataQuetzalLa by lazy { mapSecDataQuetzalOnMap.renamedSecs(mapSecNamesQuetzalLa) }

private fun Map<Int, MoveInfo>.renamed(names: Map<Int, String>) = mapValues { (id, m) -> names[id]?.let { m.copy(name = it) } ?: m }
private fun Map<Int, MapSecInfo>.renamedSecs(names: Map<Int, String>) = mapValues { (id, m) -> names[id]?.let { m.copy(name = it) } ?: m }

// FireRed's map sections, boxes and region maps (the ROM keeps FireRed's art: RomArt rebuilds it from
// Recharged Yellow's own ROM) under the game's title-cased names ("Undergound Path" included).
private val mapSecDataRechargedYellow by lazy { mapSecData.renamedSecs(mapSecNamesRechargedYellow) }

private fun quetzalMoves(lang: Int) = if (quetzalV084) when (lang) { 1 -> moveDataQuetzalV084Es; 2 -> moveDataQuetzalV084La; else -> moveDataQuetzalV084 }
    else when (lang) { 1 -> moveDataQuetzalEs; 2 -> moveDataQuetzalLa; else -> moveDataQuetzal }
private fun quetzalItems(lang: Int) = when (lang) {
    1 -> itemNamesQuetzalSpanish
    2 -> if (quetzalV1) itemNamesQuetzalLatamV1 else itemNamesQuetzalLatam
    else -> itemNamesQuetzal
}
private val itemNamesQuetzalLatamV1 by lazy { itemNamesQuetzalLatam + itemNamesQuetzalLaV1Changes }

/** Quetzal Alpha 9 v1: v0's tables but the Latin American names of Johto's key items (v0's were Portuguese,
 * [itemNamesQuetzalLaV1Changes]). Set with [activeGame] by the Poller. */
var quetzalV1 = false
private fun quetzalMapSecs(lang: Int) = if (quetzalV084) (if (lang == 1) mapSecDataQuetzalV084Es else mapSecDataQuetzalV084)
    else when (lang) { 1 -> mapSecDataQuetzalEs; 2 -> mapSecDataQuetzalLa; else -> mapSecDataQuetzalOnMap }

/**
 * Quetzal Alpha 0.8.4 (English / Spanish, and their Moemon Hotfix builds): the release before Alpha 9, Hoenn alone. Its
 * species, items and names (every language) are Alpha 9's by id, 16 moves have powers / types of their own
 * ([moveDataQuetzalV084Changes]), and its region map is Emerald's Hoenn with Emerald's section rects under Alpha 9's
 * names (its gRegionMapEntries hold one language: English or Spanish by build). Set with [activeGame] by the Poller.
 */
var quetzalV084 = false
private val moveDataQuetzalV084 by lazy { moveDataQuetzal + moveDataQuetzalV084Changes }
private val moveDataQuetzalV084Es by lazy { moveDataQuetzalV084.renamed(moveNamesQuetzalEs) }
private val moveDataQuetzalV084La by lazy { moveDataQuetzalV084.renamed(moveNamesQuetzalLa) }
private val mapSecDataQuetzalV084: Map<Int, MapSecInfo> by lazy {
    mapSecDataQuetzal.filterKeys { it < 0x100 }.mapValues { (id, q) ->
        mapSecDataEmerald[id]?.let { em -> q.copy(region = em.region, x = em.x, y = em.y, w = em.w, h = em.h) } ?: q
    }
}
private val mapSecDataQuetzalV084Es by lazy { mapSecDataQuetzalV084.renamedSecs(mapSecNamesQuetzalEs) }

// Seaglass's own Hoenn art (RomArt's regionmap/seaglass.png) on Emerald's tilemap and grid.
private val regionMapImagesSeaglass = arrayOf("seaglass")

private val regionMapImagesRechargedEmerald = arrayOf("recharged_emerald")

val activeRegionMapImages: Array<String> get() = when {
    redBlue -> arrayOf(Gen1Art.RED_BLUE_TOWN_MAP_NAME)   // Red's / Blue's town map, in their own colours (Gen1Art)
    pureRgb -> arrayOf(Gen1Art.pureTownMapName(activeGame))   // PureRed's / PureBlue's, in each one's colours (Gen1Art)
    gen4 -> emptyArray()   // Sinnoh's map comes from RegionMapModel's own; Johto / Kanto's aren't read yet
    yellow -> arrayOf("yellow")   // its town map, rebuilt from the ROM (Gen1Art)
    polished -> Gen2Art.POLISHED_TOWN_MAPS   // Johto, Kanto and the Orange Islands, from the ROM
    prism -> Gen2Art.PRISM_TOWN_MAPS   // Naljo, Rijon, Johto, Kanto, Sevii, Tunod
    crystalClear -> Gen2Art.CRYSTAL_CLEAR_TOWN_MAPS
    goldSilver -> Gen2Art.GOLD_SILVER_TOWN_MAPS
    crystal -> Gen2Art.CRYSTAL_TOWN_MAPS   // the POKéGEAR's Johto and Kanto maps, rebuilt from the ROM (Gen2Art)
    unbound -> regionMapImagesUnbound
    seaglass -> regionMapImagesSeaglass
    // Recharged Emerald's own Hoenn (RomArt's RE_REGION_*), on Emerald's layout: Emerald's boxes and cursor grid.
    emerald && runningEmeraldHack != null -> regionMapImagesRechargedEmerald
    emerald || tmt2 || eliteRedux -> regionMapImagesEmerald
    hns -> regionMapImagesHns
    lazarus -> regionMapImagesLazarus
    soulGold -> regionMapImagesSoulGold
    rogue -> regionMapImagesRogue
    glazed -> regionMapImagesGlazed
    imperium -> regionMapImagesImperium
    quetzal -> if (quetzalV084) regionMapImagesEmerald else regionMapImagesQuetzalOnMap
    rowe -> regionMapImagesRowe
    // Its own world map (Emerald's region_map.c, its art: RomArt's MM_REGION_*), the same in every release.
    mariomon -> regionMapImagesMariomon
    // Their own maps (the Orange Archipelago, Galar), drawn from the ROM (RomRegionMap) - none bundled.
    orangeIslands || swordShield || gsChronicles || frHack?.ownRegionMap == true -> emptyArray()
    // Team Rocket Edition: Dragonsden's Kanto / Sevii / Johto maps aren't read yet - the MAP tab names the place.
    teamRocket -> emptyArray()
    // Wishes of Tomorrow's JOKAIM map, rebuilt from its ROM (RomArt's WSH_REGION_*).
    wishes -> regionMapImagesWishes
    // Dreamstone Mysteries' Cormoria map, rebuilt from its ROM (RomArt's DSM_REGION_*).
    dreamstone -> regionMapImagesDreamstone
    else -> regionMapImages
}

/**
 * Unbound reindexes species/items vs vanilla so the bundled Gen 3 PNGs don't
 * match it. Mon + item icons are fetched live from the running game and cached
 * (UnboundIconSource), like its region map (RomRegionMap).
 */
val activeMonSpriteDir: String get() = when {
    unbound -> "pokemon-unbound"
    redBlue -> Gen1Art.RED_BLUE_ICONS
    pureRgb -> Gen1Art.pureIcons(activeGame)
    yellow -> Gen1Art.YELLOW_ICONS   // its own party icons, rebuilt from the ROM
    polished -> Gen2Art.POLISHED_ICONS
    black2 -> NdsArt.BLACK2_ICONS
    black -> NdsArt.BLACK_ICONS
    platinum -> NdsArt.PLATINUM_ICONS   // the cart's icon archive, rebuilt from it (NdsArt)
    heartGold -> NdsArt.HEARTGOLD_ICONS
    prism -> Gen2Art.PRISM_ICONS
    crystalClear -> Gen2Art.CRYSTAL_CLEAR_ICONS
    goldSilver -> Gen2Art.GOLD_SILVER_ICONS
    crystal -> Gen2Art.CRYSTAL_ICONS
    else -> "pokemon"
}
val activeItemSpriteDir: String? get() = when {
    unbound -> "items-unbound"
    yellow -> null   // Gen 1 has no item icons
    black2 -> NdsArt.BLACK2_ITEMS
    black -> NdsArt.BLACK_ITEMS
    heartGold -> NdsArt.HEARTGOLD_ITEMS   // the cart's item_icon.narc, rebuilt from it (NdsArt)
    platinum -> NdsArt.PLATINUM_ITEMS
    crystal -> null   // nor has Gen 2
    else -> "items"
}

